function validate([words, s]) {
  if (!Array.isArray(words) || words.length < 1 || words.length > 1000) return 'words needs 1 to 1000 strings.';
  if (typeof s !== 'string' || s.length < 1 || s.length > 10) return 's must have 1 to 10 characters.';
  if (!/^[a-z]+$/.test(s)) return 's uses lowercase letters only.';
  for (const word of words) {
    if (typeof word !== 'string' || word.length < 1 || word.length > 10) return 'Each word has 1 to 10 characters.';
    if (!/^[a-z]+$/.test(word)) return 'Words use lowercase letters only.';
  }
  return null;
}

