function countPrefixes(words, s) {
  const prefixes = new Set();
  for (let end = 1; end <= s.length; end++) prefixes.add(s.substring(0, end));
  let total = 0;
  for (let i = 0; i < words.length; i++) if (prefixes.has(words[i])) total++;
  return total;
}

