function generate(rand, size) {
  const letters = size === 'large' ? 'abc' : 'ab';
  const word = (min, max) => {
    const length = min + Math.floor(rand() * (max - min + 1));
    let text = '';
    for (let i = 0; i < length; i++) text += letters[Math.floor(rand() * letters.length)];
    return text;
  };
  const s = size === 'large' ? word(6, 10) : word(1, 5);
  const n = size === 'large' ? 1000 : 1 + Math.floor(rand() * 8);
  const words = [];
  for (let i = 0; i < n; i++) {
    // About half the entries are cut from s itself so that matches are common.
    if (rand() < 0.5) words.push(s.slice(0, 1 + Math.floor(rand() * s.length)));
    else words.push(word(1, size === 'large' ? 10 : 6));
  }
  return [words, s];
}
